Done. Summary:

**Problem:** `lru.go` tracked recency only via a slice updated on `Put`, so `Get` never marked a key as used — a just-read key could be evicted.

**Fix (lru.go):** Replaced the `order []int` slice with a doubly-linked list + map (`map[int]*node` with sentinel head/tail). Both `Get` (on hit) and `Put` (insert or update) move the node to the front;

Done. Summary:

**Problem:** `lru.go` tracked recency only via a slice updated on `Put`, so `Get` never marked a key as used — a just-read key could be evicted.

**Fix (lru.go):** Replaced the `order []int` slice with a doubly-linked list + map (`map[int]*node` with sentinel head/tail). Both `Get` (on hit) and `Put` (insert or update) move the node to the front;

package lru

// LRUCache is a fixed-capacity least-recently-used cache mapping int keys to
// int values.
type LRUCache struct {
	capacity int
	order    []int // BUG: order is only updated on Put, not on Get
	data     map[int]int
}

// NewLRUCache returns a new cache that holds at most capacity entries.
func NewLRUCache(capacity int) *LRUCache {
	return &LRUCache{
		capacity: capacity,
		order:    make([]int, 0, capacity),
		data:     make(map[int]int, capacity),
	}
}

// Get returns the value for key and whether it was present.
func (c *LRUCache) Get(key int) (int, bool) {
	v, ok := c.data[key]
	return v, ok
}

// Put inserts or updates the value for key, evicting the least recently used
// entry if the cache is over capacity.
func (c *LRUCache) Put(key, value int) {
	if _, exists := c.data[key]; !exists {
		c.order = append(c.order, key)
	}
	c.data[key] = value

	if len(c.data) > c.capacity {
		oldest := c.order[0]
		c.order = c.order[1:]
		delete(c.data, oldest)
	}
}

