	c.Put(3, 3) // must evict key 2, not key 1
	if _, ok := c.Get(1); !ok {
		t.Error("key 1 was evicted even though it was just read")
	}
	if _, ok := c.Get(2); ok {
		t.Error("key 2 should have been evicted as least recently used")
	}
	if v, ok := c.Get(3); !ok || v != 3 {
		t.Fatalf("Get(3) = %d, %v; want 3, true", v, ok)
	}
}

func TestPutUpdateCountsAsUse(t *testing.T) {
	c := NewLRUCache(2)
	c.Put(1, 1)
	c.Put(2, 2)
	c.Put(1, 10) // update marks 1 as most recently used
	c.Put(3, 3)
	if v, ok := c.Get(1); !ok || v != 10 {
		t.Fatalf("Get(1) = %d, %v; want 10, true", v, ok)
	}
	if _, ok := c.Get(2); ok {
		t.Error("key 2 should have been evicted")
	}
}

func TestGetAbsentKey(t *testing.T) {
	c := NewLRUCache(1)
	if v, ok := c.Get(42); ok || v != 0 {
		t.Fatalf("Get(42) = %d, %v; want 0, false", v, ok)
	}
}

func TestEvictionOrderByMixedAccess(t *testing.T) {
	c := NewLRUCache(3)
	c.Put(1, 1)
	c.Put(2, 2)
	c.Put(3, 3)
	c.Get(1) // order: 3, 2, 1
	c.Get(2) // order: 1, 3, 2
	c.Put(4, 4) // evicts 3
	for _, k := range []int{1, 2, 4} {
		if _, ok := c.Get(k); !ok {
			t.Errorf("key %d should still be present", k)
		}
	}
	if _, ok := c.Get(3); ok {
		t.Error("key 3 should have been evicted")
	}
